import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"ユーザーマニュアル","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/index.md","filePath":"ja-JP/user-guide/index.md","lastUpdated":1785993908000}'),s={name:"ja-JP/user-guide/index.md"};function n(i,t,l,g,h,d){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="ユーザーマニュアル" tabindex="-1">ユーザーマニュアル <a class="header-anchor" href="#ユーザーマニュアル" aria-label="Permalink to &quot;ユーザーマニュアル&quot;">​</a></h1><p>Lertaro は、キーボード操作を中心とした Windows 向けの高速ファイル検索ランチャーです。ローカルドライブ (NTFS と ReFS はそれぞれの変更ジャーナル経由、それ以外のファイルシステムは直接監視) とネットワーク共有をバックグラウンドでインデックス化し、任意のファイル・フォルダー・アプリケーションに一瞬でジャンプできるようにします。</p><p>このマニュアルでは、日常的に使うユーザーに必要なことをすべて扱います:</p><ul><li><strong><a href="./getting-started.html">はじめに</a></strong> — Lertaro のインストール方法と、3 つの検索ウィンドウ (メイン、クイック、インライン) の理解。</li><li><strong><a href="./search-syntax.html">検索構文</a></strong> — あいまい検索、除外/完全一致/前方一致/後方一致演算子、OR グループ、ドライブ指定、パスモード、中国語ファイル名向けのピンインエイリアス。</li><li><strong><a href="./hotkeys.html">ホットキー</a></strong> — 設定可能なすべてのショートカットとハードコードされたキー、既定の割り当て。</li><li><strong><a href="./actions-and-preview.html">アクションメニューとプレビュー</a></strong> — 右クリック風のアクションリストと QuickLook プレビューパネル。</li><li><strong><a href="./instant-answers.html">インスタントアンサーとキーワードショートカット</a></strong> — 電卓、環境変数、コマンド実行ショートカット、そしてプロセスマネージャー・ウィンドウ切り替え・ブラウザデータ・設定検索・ウェブ検索といったキーワードで起動するプラグイン。</li><li><strong><a href="./cli.html">コマンドライン検索 (lff)</a></strong> — ターミナルから検索するための fzf スタイルの CLI コンパニオン。</li><li><strong><a href="./uri-protocol.html">URI プロトコル (lertaro://)</a></strong> — リンク、別のアプリ、またはスクリプトから、検索や特定の設定に直接ジャンプする方法。</li><li><strong><a href="./file-manager-support.html">対応ファイルマネージャー</a></strong> — Lertaro がドッキングできる、クイックナビゲーションを起動できる、または現在のフォルダーを検出できるファイルマネージャーとファイル選択ダイアログ。</li><li><strong><a href="./settings/">設定リファレンス</a></strong> — すべての設定ページ、タブ、オプションの一覧。</li><li><strong><a href="./troubleshooting.html">トラブルシューティング</a></strong> — よくある問題とその解決方法。</li><li><strong><a href="./donate.html">寄付</a></strong> — Lertaro が役に立ったと感じていただけたなら。</li></ul><p>Lertaro を初めてセットアップする場合は、<strong>はじめに</strong> から始めてください。</p>',5)])])}const m=r(s,[["render",n]]);export{p as __pageData,m as default};
